    /**
     * @method
     * @name bitbns#fetchMarkets
     * @description retrieves data on all markets for bitbns
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public CompletableFuture<Object> fetchMarkets(Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            List<Object> response = (this.wwwGetOrderFetchMarkets(parameters)).join();
            //
            //     [
            //         {
            //             "id":"BTC",
            //             "symbol":"BTC/INR",
            //             "base":"BTC",
            //             "quote":"INR",
            //             "baseId":"BTC",
            //             "quoteId":"",
            //             "active":true,
            //             "limits":{
            //                 "amount":{"min":"0.00017376","max":20},
            //                 "price":{"min":2762353.2359999996,"max":6445490.883999999},
            //                 "cost":{"min":800,"max":128909817.67999998}
            //             },
            //             "precision":{
            //                 "amount":8,
            //                 "price":2
            //             },
            //             "info":{}
            //         },
            //     ]
            //
            List<Object> result = new ArrayList<Object>(Arrays.asList());
            List<Object> rawMarkets = this.toArray(response);
            for (var i = 0; i < ((List<?>)rawMarkets).size(); i++)
            {
                Object market = (rawMarkets == null || i < 0 || i >= rawMarkets.size() ? null : rawMarkets.get(i));
                String id = this.safeString(market, "id");
                String baseId = this.safeString(market, "base");
                String quoteId = this.safeString(market, "quote");
                String base = this.safeCurrencyCode(baseId, (Map<String, Object>) null);
                String quote = this.safeCurrencyCode(quoteId, (Map<String, Object>) null);
                if ((java.util.Objects.equals(baseId, null)) || (java.util.Objects.equals(base, null)) || (java.util.Objects.equals(quote, null)))
                {
                    continue;
                }
                Map<String, Object> marketPrecision = (Map<String, Object>) this.safeDict(market, "precision", new HashMap<String, Object>() {{}});
                Map<String, Object> marketLimits = (Map<String, Object>) this.safeDict(market, "limits", new HashMap<String, Object>() {{}});
                Map<String, Object> amountLimits = (Map<String, Object>) this.safeDict(marketLimits, "amount", new HashMap<String, Object>() {{}});
                Map<String, Object> priceLimits = (Map<String, Object>) this.safeDict(marketLimits, "price", new HashMap<String, Object>() {{}});
                Map<String, Object> costLimits = (Map<String, Object>) this.safeDict(marketLimits, "cost", new HashMap<String, Object>() {{}});
                Boolean usdt = (java.util.Objects.equals(quoteId, "USDT"));
                // INR markets don't need a _INR prefix
                String uppercaseId = baseId;
                if (Boolean.TRUE.equals(usdt))
                {
                    uppercaseId = (((baseId + "_") + quoteId));
                }
                ((List<Object>)result).add(Helpers.newMap(
                    "id", id,
                    "uppercaseId", uppercaseId,
                    "symbol", ((base + "/") + quote),
                    "base", base,
                    "quote", quote,
                    "settle", null,
                    "baseId", baseId,
                    "quoteId", quoteId,
                    "settleId", null,
                    "type", "spot",
                    "spot", true,
                    "margin", false,
                    "swap", false,
                    "future", false,
                    "option", false,
                    "active", this.safeBool(market, "active", (Object) null),
                    "contract", false,
                    "linear", null,
                    "inverse", null,
                    "contractSize", null,
                    "expiry", null,
                    "expiryDatetime", null,
                    "strike", null,
                    "optionType", null,
                    "precision", new HashMap<String, Object>() {{
                        put( "amount", Bitbns.this.parseNumber(Bitbns.this.parsePrecision(Bitbns.this.safeString(marketPrecision, "amount"))) );
                        put( "price", Bitbns.this.parseNumber(Bitbns.this.parsePrecision(Bitbns.this.safeString(marketPrecision, "price"))) );
                    }},
                    "limits", new HashMap<String, Object>() {{
                        put( "leverage", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "amount", new HashMap<String, Object>() {{
                            put( "min", Bitbns.this.safeNumber(amountLimits, "min", (Object) null) );
                            put( "max", Bitbns.this.safeNumber(amountLimits, "max", (Object) null) );
                        }} );
                        put( "price", new HashMap<String, Object>() {{
                            put( "min", Bitbns.this.safeNumber(priceLimits, "min", (Object) null) );
                            put( "max", Bitbns.this.safeNumber(priceLimits, "max", (Object) null) );
                        }} );
                        put( "cost", new HashMap<String, Object>() {{
                            put( "min", Bitbns.this.safeNumber(costLimits, "min", (Object) null) );
                            put( "max", Bitbns.this.safeNumber(costLimits, "max", (Object) null) );
                        }} );
                    }},
                    "created", null,
                    "info", market
                ));
            }
            return result;
        });

    }

    /**
     * @method
     * @name bitbns#fetchOrderBook
     * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public CompletableFuture<OrderBook> fetchOrderBook(Object symbol, Long limit, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> market = this.market(symbol);
            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "symbol", market.get("id") );
            }};
            if (!java.util.Objects.equals(limit, null))
            {
                request.put("limit", limit); // default 100, max 5000, see https://github.com/binance-exchange/binance-official-api-docs/blob/master/rest-api.md#order-book
            }
            Map<String, Object> response = (this.wwwGetOrderFetchOrderbook(this.extend(request, parameters))).join();
            //
            //     {
            //         "bids":[
            //             [49352.04,0.843948],
            //             [49352.03,0.742048],
            //             [49349.78,0.686239],
            //         ],
            //         "asks":[
            //             [49443.59,0.065137],
            //             [49444.63,0.098211],
            //             [49449.01,0.066309],
            //         ],
            //         "timestamp":1619172786577,
            //         "datetime":"2021-04-23T10:13:06.577Z",
            //         "nonce":""
            //     }
            //
            Long timestamp = this.safeInteger(response, "timestamp");
            return this.parseOrderBook(response, market.get("symbol"), timestamp, "bids", "asks", 0, 1, 2);
        }).thenApply(OrderBook::new);

    }

    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        //
        //     {
        //         "symbol":"BTC/INR",
        //         "info":{
        //             "highest_buy_bid":4368494.31,
        //             "lowest_sell_bid":4374835.09,
        //             "last_traded_price":4374835.09,
        //             "yes_price":4531016.27,
        //             "volume":{"max":"4569119.23","min":"4254552.13","volume":62.17722344}
        //         },
        //         "timestamp":1619100020845,
        //         "datetime":1619100020845,
        //         "high":"4569119.23",
        //         "low":"4254552.13",
        //         "bid":4368494.31,
        //         "bidVolume":"",
        //         "ask":4374835.09,
        //         "askVolume":"",
        //         "vwap":"",
        //         "open":4531016.27,
        //         "close":4374835.09,
        //         "last":4374835.09,
        //         "baseVolume":62.17722344,
        //         "quoteVolume":"",
        //         "previousClose":"",
        //         "change":-156181.1799999997,
        //         "percentage":-3.446934874943623,
        //         "average":4452925.68
        //     }
        //
        Long timestamp = this.safeInteger(ticker, "timestamp");
        String marketId = this.safeString(ticker, "symbol");
        String symbol = this.safeSymbol(marketId, market, (String) null, (String) null);
        String last = this.safeString(ticker, "last");
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", timestamp );
            put( "datetime", Bitbns.this.iso8601(timestamp) );
            put( "high", Bitbns.this.safeString(ticker, "high") );
            put( "low", Bitbns.this.safeString(ticker, "low") );
            put( "bid", Bitbns.this.safeString(ticker, "bid") );
            put( "bidVolume", Bitbns.this.safeString(ticker, "bidVolume") );
            put( "ask", Bitbns.this.safeString(ticker, "ask") );
            put( "askVolume", Bitbns.this.safeString(ticker, "askVolume") );
            put( "vwap", Bitbns.this.safeString(ticker, "vwap") );
            put( "open", Bitbns.this.safeString(ticker, "open") );
            put( "close", last );
            put( "last", last );
            put( "previousClose", Bitbns.this.safeString(ticker, "previousClose") );
            put( "change", Bitbns.this.safeString(ticker, "change") );
            put( "percentage", Bitbns.this.safeString(ticker, "percentage") );
            put( "average", Bitbns.this.safeString(ticker, "average") );
            put( "baseVolume", Bitbns.this.safeString(ticker, "baseVolume") );
            put( "quoteVolume", Bitbns.this.safeString(ticker, "quoteVolume") );
            put( "info", ticker );
        }}, market);
    }

